import{_ as s,o as i,c as e,a1 as n}from"./chunks/framework.Cv8QbFmh.js";const k=JSON.parse('{"title":"Optimus 笔记本安装 Manjaro：黑屏、便携外屏、频繁卡死与迁移 Wayland 全记录","description":"在 ASUS TUF Gaming A14（AMD 核显 + RTX 5060）上全新安装 Manjaro KDE 的完整排障记录——从 GRUB 后黑屏、NVIDIA 模块内核目录错配，到 X11 下 AMDGPU fence 死锁导致的频繁卡死；切换 Wayland 解决了 greeter 黑屏和 fence 死锁两类问题，但没有解决所有卡死。","frontmatter":{"title":"Optimus 笔记本安装 Manjaro：黑屏、便携外屏、频繁卡死与迁移 Wayland 全记录","description":"在 ASUS TUF Gaming A14（AMD 核显 + RTX 5060）上全新安装 Manjaro KDE 的完整排障记录——从 GRUB 后黑屏、NVIDIA 模块内核目录错配，到 X11 下 AMDGPU fence 死锁导致的频繁卡死；切换 Wayland 解决了 greeter 黑屏和 fence 死锁两类问题，但没有解决所有卡死。","date":"2026-10-01T00:00:00.000Z","tags":["Manjaro","NVIDIA","AMD","KDE","Wayland","Linux"],"sidebar":false},"headers":[],"relativePath":"zh/blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md","filePath":"zh/blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md"}'),t={name:"zh/blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md"};function l(o,a,d,p,h,c){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="optimus-笔记本安装-manjaro-黑屏、便携外屏、频繁卡死与迁移-wayland-全记录" tabindex="-1">Optimus 笔记本安装 Manjaro：黑屏、便携外屏、频繁卡死与迁移 Wayland 全记录 <a class="header-anchor" href="#optimus-笔记本安装-manjaro-黑屏、便携外屏、频繁卡死与迁移-wayland-全记录" aria-label="Permalink to &quot;Optimus 笔记本安装 Manjaro：黑屏、便携外屏、频繁卡死与迁移 Wayland 全记录&quot;">​</a></h1><p><code>2026-10-01</code> · Manjaro · NVIDIA · AMD · Wayland</p><p>这篇博文记录了我在 ASUS TUF Gaming A14（FA401KM）笔记本上把 Windows 11 换成 Manjaro KDE 双系统的全部经历。导致大部分痛苦的硬件细节是：这是一台 <strong>Optimus 混合显卡机器</strong>——AMD Radeon 860M 核显加 NVIDIA RTX 5060 Laptop 独显，而且<strong>内屏排线接在核显上</strong>，不在独显上。</p><h2 id="安装介质与安装流程" tabindex="-1">安装介质与安装流程 <a class="header-anchor" href="#安装介质与安装流程" aria-label="Permalink to &quot;安装介质与安装流程&quot;">​</a></h2><p>安装本身很顺利，还是老流程：</p><ol><li>用 Ventoy 制作 U 盘启动盘，把 Manjaro KDE Plasma ISO 放进去。</li><li>开机按 <code>F2</code> 进 BIOS，在 <code>Save &amp; Exit -&gt; Boot Override</code> 里选 U 盘启动。</li><li>在 Ventoy 里选 normal 模式启动镜像（有问题再退回 grub2 模式）。</li><li>进 live 环境后把 tz 设为 <code>Asia/Shanghai</code>、lang 设为 <code>zh_CN</code>，选开源驱动启动。</li><li>安装器里：全盘擦除、选<strong>带休眠</strong>的 swap（笔记本推荐）、不装办公套件。</li></ol><p>装完拔掉 U 盘重启，GRUB 菜单正常出现，Windows 和 Manjaro 都在。选择 Manjaro——<strong>黑屏</strong>。真正的工作从这里开始。</p><h2 id="第一次黑屏-rtx-5060-没有-nvidia-驱动" tabindex="-1">第一次黑屏：RTX 5060 没有 NVIDIA 驱动 <a class="header-anchor" href="#第一次黑屏-rtx-5060-没有-nvidia-驱动" aria-label="Permalink to &quot;第一次黑屏：RTX 5060 没有 NVIDIA 驱动&quot;">​</a></h2><p><code>Ctrl + Alt + F3</code> 能切进 TTY，说明内核启动正常，问题出在图形栈。查看显卡和已加载模块：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vga|3d&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsmod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia</span></span></code></pre></div><p>加载的只有 <code>nvidia_wmi_ec_backlight</code>（背光小助手，不是驱动本体）和 nouveau。RTX 5060 是 Blackwell 架构，nouveau 带不动，于是计划装官方驱动：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mhwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nonfree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0300</span></span></code></pre></div><h2 id="没有网络-手机-usb-共享联网" tabindex="-1">没有网络：手机 USB 共享联网 <a class="header-anchor" href="#没有网络-手机-usb-共享联网" aria-label="Permalink to &quot;没有网络：手机 USB 共享联网&quot;">​</a></h2><p>机器还没配 Wi-Fi，只能用安卓手机共享网络——Linux 内核自带 <code>rndis_host</code>/<code>cdc_ncm</code> 驱动，USB 共享网络即插即用：</p><ol><li>用数据线连手机，打开 USB 网络共享。</li><li><code>ip a</code> 确认出现 <code>usb0</code> 接口。</li><li>交给 NetworkManager 拿 IP，<code>ping</code> 验证。</li></ol><p>这次的一个教训：手机一直在反复掉线重连（<code>dmesg</code> 里满屏 <code>USB disconnect</code>）。下载中途断网正是后面&quot;半安装&quot;状态的元凶，所以务必用好的数据线、插原生 USB 口。</p><h2 id="mhwd-安装失败-镜像源和-dns-双双翻车" tabindex="-1">mhwd 安装失败：镜像源和 DNS 双双翻车 <a class="header-anchor" href="#mhwd-安装失败-镜像源和-dns-双双翻车" aria-label="Permalink to &quot;mhwd 安装失败：镜像源和 DNS 双双翻车&quot;">​</a></h2><p>第一次装驱动以 <code>Error: pacman failed!</code> 告终。分到的镜像源完全不可用——pacman 挑中了一个乌拉圭源，速度不到 1 字节/秒；其余镜像 DNS 解析超时。修复：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nameserver 223.5.5.5&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman-mirrors</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> China</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mhwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nonfree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0300</span></span></code></pre></div><p>换成国内镜像（TUNA/中科大/上交大）并设置可用 DNS 后，约 500 MB 的驱动几分钟就下完了。</p><h2 id="loadkmap-short-read-以及一个不存在的模块" tabindex="-1"><code>loadkmap: short read</code>，以及一个不存在的模块 <a class="header-anchor" href="#loadkmap-short-read-以及一个不存在的模块" aria-label="Permalink to &quot;\`loadkmap: short read\`，以及一个不存在的模块&quot;">​</a></h2><p>驱动装完，下次开机显示 <code>loadkmap: short read</code>。这条消息本身只是 initramfs 键盘映射的无害警告（它真正成为主角的一次，见<a href="./2026-08-11-manjaro-nvidia-black-screen.html">早前那篇博文</a>）。真正的故障仍然是 SDDM：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sddm[755]: Failed to read display number from pipe</span></span>
<span class="line"><span>Could not start Display server on vt 2</span></span></code></pre></div><p>而且模块压根没加载：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modprobe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># modprobe: FATAL: Module nvidia not found in directory /lib/modules/7.1.8-1-MANJARO</span></span></code></pre></div><p>两个常见嫌疑很快被排除：</p><ul><li><strong>Secure Boot</strong>：BIOS 里已经是关闭状态。</li><li><strong>驱动/用户态版本错配</strong>：<code>linux71-nvidia-open 610.57.04-6</code> 与 <code>nvidia-utils 610.57.04-1</code> 完全对齐。</li></ul><p>真凶在列出驱动包文件时现形：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux71-nvidia-open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\\.ko&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /usr/lib/modules/7.1.9-1-MANJARO/extramodules/nvidia-drm.ko.zst</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ...</span></span></code></pre></div><p>驱动模块是给 <strong>7.1.9</strong> 内核编译的，而系统装着、跑着的是 <strong>7.1.8</strong>。pacman 数据库里包是&quot;已安装&quot;，但对正在运行的内核来说模块不存在。单独重装驱动包无济于事，正解是完整升级让内核和模块对齐：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p>进入 7.1.9 后 <code>modprobe nvidia</code> 成功，<code>nvidia-smi</code> 打出了 RTX 5060 的表格。</p><h2 id="第二次黑屏-x-渲染正常-画面到不了内屏" tabindex="-1">第二次黑屏：X 渲染正常，画面到不了内屏 <a class="header-anchor" href="#第二次黑屏-x-渲染正常-画面到不了内屏" aria-label="Permalink to &quot;第二次黑屏：X 渲染正常，画面到不了内屏&quot;">​</a></h2><p>驱动通了，下次开机依然黑屏，左上角一个光标。<code>nvidia-smi</code> 里甚至能看到 <code>Xorg</code> 和 <code>sddm-greeter-qt6</code> 已经跑在 GPU 上——X 在渲染，但画面从没送到内屏。</p><p>枚举 DRM 接口解释了一切：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>card0-DP-8, card0-eDP-2, card0-HDMI-A-2        # NVIDIA 独显</span></span>
<span class="line"><span>card1-DP-1..7, card1-eDP-1, card1-HDMI-A-1     # AMD 核显</span></span>
<span class="line"><span>card1-eDP-1: connected</span></span></code></pre></div><p>内屏（<code>eDP-1</code>）挂在 <strong>AMD 核显</strong>上，而 mhwd 生成的 <code>/etc/X11/xorg.conf.d/90-mhwd.conf</code> 是老式 <code>nvidia-xconfig</code> 单显卡模板：没有 <code>OutputClass</code>、没有 PRIME 反向输出链、没有 <code>AllowEmptyInitialConfiguration</code>。X 在独显上渲染，没有任何通道把画面送到接在核显上的内屏。</p><p>X11 侧的修复：</p><ol><li>把老配置挪走：<code>sudo mv /etc/X11/xorg.conf.d/90-mhwd.conf /etc/X11/xorg.conf.d/90-mhwd.conf.bak</code></li><li>确认 <code>nvidia_drm</code> 的 modeset 已启用（<code>/etc/modprobe.d/</code> 里的 <code>options nvidia_drm modeset=1</code>；新版 nvidia-open 默认已开）。</li><li>清理 mhwd 留在 <code>/etc/modprobe.d/mhwd-gpu.conf</code> 里的过时屏蔽（<code>blacklist drm</code>、<code>blacklist ttm</code>、<code>blacklist drm_kms_helper</code>）——那是给上古 390xx 驱动防冲突用的，对 nvidia-open 有百害而无一利。</li><li><code>sudo mkinitcpio -P</code> 后重启。</li></ol><h2 id="便携外屏阶段" tabindex="-1">便携外屏阶段 <a class="header-anchor" href="#便携外屏阶段" aria-label="Permalink to &quot;便携外屏阶段&quot;">​</a></h2><p>即便如此，SDDM 在内屏上仍然一片漆黑。决定性的实验：用 HDMI 接上便携外接屏——登录界面<strong>只出现在外屏上</strong>，而登进 KDE 之后内屏也跟着亮了。</p><p>这个现象补上了最后一块拼图：greeter 阶段只激活了 X 的默认输出（独显的 HDMI），而 KDE 的 kwin 在会话启动后会启用所有检测到的输出。整条&quot;渲染到面板&quot;的路径都是通的，缺的只是 greeter 阶段这一环。</p><h2 id="x11-下的频繁卡死-amdgpu-fence-死锁" tabindex="-1">X11 下的频繁卡死：AMDGPU Fence 死锁 <a class="header-anchor" href="#x11-下的频繁卡死-amdgpu-fence-死锁" aria-label="Permalink to &quot;X11 下的频繁卡死：AMDGPU Fence 死锁&quot;">​</a></h2><p>故事还没完。X11 下机器开始频繁卡死：打字打着一锁死，快捷键全无响应，只能长按电源键强制关机。两个很有信息量的规律：</p><ul><li>一整天只接便携屏用：一次都不卡。</li><li>卡死时<strong>内屏先冻结</strong>，便携屏有时还能动一会儿。</li></ul><p>内核日志给出了死锁的直接证据：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INFO: task kworker/u64:* blocked for more than 122 seconds.</span></span>
<span class="line"><span>Workqueue: events_unbound commit_work</span></span>
<span class="line"><span>amdgpu_display_get_crtc_scanoutpos</span></span>
<span class="line"><span>dma_fence_default_wait</span></span>
<span class="line"><span>drm_atomic_helper_wait_for_fences</span></span>
<span class="line"><span>commit_tail</span></span></code></pre></div><p>每次卡死都是同一条时间线：KDE X11/KScreen 在登录后立刻通过 XRandR 恢复双屏布局，AMDGPU 的 DRM 原子提交等待一个永远不会完成的 DMA fence，显示工作队列线程进入不可中断的 <code>D</code> 状态，由核显驱动的内屏率先停止更新（独显驱动的便携屏多撑一阵）。</p><p>沿途排除过的嫌疑：把 KDE 里接电源/电池的挂起动作都改成&quot;无操作&quot;，拔掉便携屏后照样卡死；没启动过 RustDesk 的启动里也复现过卡死。临时缓解手段是停掉 <code>kscreen_backend_launcher</code> 让 KDE 不再反复提交显示配置，但已经阻塞的内核线程只能靠重启清掉。</p><h2 id="sddm-和会话切换到-wayland" tabindex="-1">SDDM 和会话切换到 Wayland <a class="header-anchor" href="#sddm-和会话切换到-wayland" aria-label="Permalink to &quot;SDDM 和会话切换到 Wayland&quot;">​</a></h2><p>与其继续跟 X11 PRIME 的边角问题和 fence 死锁搏斗，不如把显示管理器和会话整体迁到 Wayland，直接绕开反向 PRIME 输出通路：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sddm.conf.d/99-wayland.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[General]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DisplayServer=wayland</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><p>重启后，不需要任何外接屏，SDDM 直接在内屏显示登录界面，登录 Plasma (Wayland) 会话一切正常。同样的双屏布局再没触发过任何 <code>dma_fence</code> 等待、阻塞任务或 GPU 重置，X11 的这类死锁就此绝迹。</p><h2 id="经验总结" tabindex="-1">经验总结 <a class="header-anchor" href="#经验总结" aria-label="Permalink to &quot;经验总结&quot;">​</a></h2><ul><li><strong>混合显卡笔记本先查显示拓扑。</strong> <code>ls /sys/class/drm/card*/</code> 一眼看出内屏归哪个 GPU；这台机器内屏在核显上，一切&quot;NVIDIA 显卡负责显示&quot;的 X11 默认假设从第一天起就是错的。</li><li><strong>驱动包已安装但 <code>modprobe</code> 报 <code>Module not found</code>，大概率是内核/模块目录错配。</strong> 用 <code>pacman -Ql</code> 列出包文件，比对版本目录和 <code>uname -r</code>；解法是完整的 <code>pacman -Syu</code>，不是重装驱动。</li><li><strong>TTY 还能进的黑屏是用户态图形问题，不是装坏了系统。</strong> GRUB 里临时加 nomodeset 是很好的单次诊断手段。</li><li><strong>USB 共享网络是全新安装最快上网方式</strong>——但不稳的数据线会造成半完成的安装事务，正是上面&quot;已安装却失踪&quot;那类问题的温床。</li><li><strong>内屏在核显上的 Optimus 机器，Wayland 是阻力最小的路。</strong> 它同时消灭了 greeter 黑屏和 X11 的 AMDGPU fence 死锁两类问题。</li><li>日志里那些 <code>nvidia_wmi_ec_backlight</code> 的 ACPI 报错在整个过程中都只是噪音，和上述任何一次故障无关（直到 2026-09，EC 背光控制才真正坏掉，成为另一个故事）。</li></ul><h2 id="后续-2026-10-卡死并没有完全绝迹" tabindex="-1">后续（2026-10）：卡死并没有完全绝迹 <a class="header-anchor" href="#后续-2026-10-卡死并没有完全绝迹" aria-label="Permalink to &quot;后续（2026-10）：卡死并没有完全绝迹&quot;">​</a></h2><p>补一句后续：切到 Wayland 后绝迹的只是 X11 那一类死锁。2026-10 机器又卡死过几次，其中 10-04 那次全屏冻住，内核日志里 amdgpu <code>Pageflip timed out! This is a bug in the amdgpu kernel driver</code> 刷了 312 条——核显显示层的提交超时，是上游驱动的 bug，和 X11 的 dma_fence 死锁不是一回事，也没有稳定的触发规律。目前没有解法，兜底手段是 REISUB 急救重启。结论修正为：Wayland 解决的是 greeter 黑屏和 X11 fence 死锁两类问题，不是所有卡死。</p>`,57)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
